const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

import { StripeWebhookPayload } from './fixtures'
import crypto from 'crypto'

export interface ConnectorConfig {
  stripeWebhookSecret: string
  mailchimpApiKey: string
  mailchimpAudienceId: string
  fetch?: typeof fetch
}

export interface ConnectorResult {
  success: boolean
  memberId: string
}

export interface MailchimpMemberResponse {
  id: string
  email_address: string
  status: string
  tags: string[]
  merge_fields: Record<string, string>
}

async function verifyStripeSignature(
  payload: string,
  signature: string,
  secret: string
): Promise<void> {
  const elements = signature.split(',')
  const timestamp = elements.find(e => e.startsWith('t='))?.slice(2)
  const v1 = elements.find(e => e.startsWith('v1='))?.slice(3)

  if (!timestamp || !v1) {
    throw new Error('Invalid Stripe signature format')
  }

  const signedPayload = `${timestamp}.${payload}`
  const expectedSignature = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex')

  if (v1 !== expectedSignature) {
    throw new Error('Invalid Stripe signature')
  }

  const timestampNum = parseInt(timestamp, 10)
  const now = Math.floor(Date.now() / 1000)
  if (now - timestampNum > 300) {
    throw new Error('Stripe signature timestamp too old')
  }
}

function extractPlanId(payload: StripeWebhookPayload): string {
  const planId = payload.data.object.metadata?.plan
  if (!planId) {
    throw new Error('Missing plan ID in metadata.plan')
  }
  return planId
}

function extractEmail(payload: StripeWebhookPayload): string {
  const email = payload.data.object.customer_email
  if (!email) {
    throw new Error('Missing customer_email in payload')
  }
  return email.toLowerCase().trim()
}

function extractMailchimpDatacenter(apiKey: string): string {
  const parts = apiKey.split('-')
  if (parts.length < 2) {
    throw new Error('Invalid Mailchimp API key format. Expected format: xxxxxxxx-us1')
  }
  return parts[parts.length - 1]
}

function buildMailchimpUrl(datacenter: string, audienceId: string): string {
  return `https://${datacenter}.api.mailchimp.com/3.0/lists/${audienceId}/members`
}

function buildMemberPayload(email: string, planId: string): Record<string, unknown> {
  const emailHash = crypto
    .createHash('md5')
    .update(email.toLowerCase())
    .digest('hex')

  return {
    email_address: email,
    status_if_new: 'subscribed',
    tags: [planId],
    merge_fields: {
      INTERESTS: planId,
    },
  }
}

async function callMailchimpApi(
  url: string,
  apiKey: string,
  payload: Record<string, unknown>,
  fetchImpl: typeof fetch
): Promise<MailchimpMemberResponse> {
  const auth = `anystring:${apiKey}`
  const authHeader = 'Basic ' + Buffer.from(auth).toString('base64')

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': authHeader,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Mailchimp API error ${response.status} ${response.url}: ${errorText}`)
  }

  return response.json() as Promise<MailchimpMemberResponse>
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const fetchImpl = config.fetch ?? fetch

  const email = extractEmail(payload)
  const planId = extractPlanId(payload)

  const datacenter = extractMailchimpDatacenter(config.mailchimpApiKey)
  const url = buildMailchimpUrl(datacenter, config.mailchimpAudienceId)
  const payload_body = buildMemberPayload(email, planId)

  const response = await callMailchimpApi(url, config.mailchimpApiKey, payload_body, fetchImpl)

  return {
    success: true,
    memberId: response.id,
  }
}

export async function handleWebhook(
  request: Request,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const signature = request.headers.get('stripe-signature')
  if (!signature) {
    throw new Error('Missing stripe-signature header')
  }

  const rawBody = await request.text()
  await verifyStripeSignature(rawBody, signature, config.stripeWebhookSecret)

  const payload = JSON.parse(rawBody) as StripeWebhookPayload

  if (payload.type !== 'checkout.session.completed') {
    throw new Error(`Unhandled event type: ${payload.type}`)
  }

  return handle(payload, config)
}

